-- Article center local seed with 100 articles for org 29
-- Import with:
-- docker exec -i article-sentinel-mysql mysql -uroot -p'Holmes64125135' article_sentinel < scripts/article_center_seed_100.sql

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS `xt_article` (
  `id` BIGINT UNSIGNED NOT NULL,
  `orgid` BIGINT UNSIGNED NOT NULL,
  `title` VARCHAR(255) NOT NULL DEFAULT '',
  `short_title` VARCHAR(255) NOT NULL DEFAULT '',
  `rich_title` TEXT NULL,
  `keyword` VARCHAR(255) NOT NULL DEFAULT '',
  `desc` TEXT NULL,
  `state` TINYINT NOT NULL DEFAULT 0,
  `publish_at_time` DATETIME NULL,
  `update_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_org_state_id` (`orgid`, `state`, `id`),
  KEY `idx_org_publish` (`orgid`, `publish_at_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `xt_article_info` (
  `article_id` BIGINT UNSIGNED NOT NULL,
  `body` LONGTEXT NULL,
  `update_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`article_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM `xt_article_info` WHERE `article_id` BETWEEN 9110001 AND 9110100;
DELETE FROM `xt_article` WHERE `id` BETWEEN 9110001 AND 9110100;



SET FOREIGN_KEY_CHECKS = 1;
